/**
 * CmdCraft service worker: lets the site work offline after the first visit.
 * Strategy: NETWORK FIRST (so a deploy is picked up immediately, no stale-file mixing), with a 4 s timeout, then the cache.
 * On install it also pre-caches every file listed in sw-assets.json (generated by tools/build-assets.js).
 * Only GET requests to this site and to the CDNs the pages use are cached; Firebase, analytics and other APIs are never touched.
 * Bump CACHE when this strategy changes.
 */
const CACHE = "cmdcraft-v1";
const CDN_HOSTS = ["cdnjs.cloudflare.com", "cdn.tailwindcss.com", "fonts.googleapis.com", "fonts.gstatic.com", "www.gstatic.com"];

self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    try {
      const res = await fetch("sw-assets.json", { cache: "no-store" });
      const manifest = await res.json();
      const list = manifest.files || [];
      // third-party files the pages need (SQLite engine, CSS framework): cached opaque so they work offline from the first visit
      await Promise.all((manifest.external || []).map(async u => { try { await cache.add(new Request(u, { mode: "no-cors" })); } catch (e) { /* skipped */ } }));
      // one by one: a single missing file must not abort the whole install
      await Promise.all(list.map(async f => { try { await cache.add(new Request(f, { cache: "reload" })); } catch (e) { /* skipped */ } }));
    } catch (e) { /* no list yet: runtime caching still works */ }
    self.skipWaiting();
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k.startsWith("cmdcraft-") && k !== CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});

function cacheable(url) {
  if (url.origin === self.location.origin) return true;
  return CDN_HOSTS.includes(url.hostname) && (url.hostname !== "www.gstatic.com" || url.pathname.startsWith("/firebasejs/"));
}

self.addEventListener("fetch", event => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (!cacheable(url)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    try {
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 4000);
      const res = await fetch(req, { signal: ctrl.signal });
      clearTimeout(timer);
      if (res && (res.ok || res.type === "opaque")) cache.put(req, res.clone());
      return res;
    } catch (e) {
      const hit = await cache.match(req, { ignoreSearch: req.mode === "navigate" });
      if (hit) return hit;
      if (req.mode === "navigate") {                       // offline and never visited: fall back to the hub
        const home = await cache.match("./") || await cache.match("index.html");
        if (home) return home;
      }
      return new Response("Offline and not cached yet.", { status: 503, headers: { "Content-Type": "text/plain" } });
    }
  })());
});
